-- Framework targets transcribed from the supplied November 2569 workbooks.
-- Workbook headcounts are deliberately not imported; the application reads actual personnel from the live registry.
-- Nursing target rows exclude explicit leadership rows; source discrepancies are retained as group-level residuals.
create table if not exists public.manpower_targets (
 report_type text not null check (report_type in ('nursing','support')),
 source_period text not null,
 group_name text not null,
 unit_name text not null,
 position text not null,
 quota integer,
 sort_group integer not null default 0,
 sort_unit integer not null default 0,
 source_note text,
 primary key (report_type,source_period,group_name,unit_name,position),
 check (quota is null or quota >= 0)
);
alter table public.manpower_targets enable row level security;
grant select on public.manpower_targets to authenticated;
drop policy if exists manpower_targets_select on public.manpower_targets;
create policy manpower_targets_select on public.manpower_targets for select to authenticated using (my_role()<>'none');
on conflict (report_type,source_period,group_name,unit_name,position) do update set quota=excluded.quota,sort_group=excluded.sort_group,sort_unit=excluded.sort_unit,source_note=excluded.source_note;

-- The support workbook footer lists 46 building-attendant positions, while its unit rows account for 45.
-- Keep the one-position remainder visible at group level rather than assigning it to a guessed unit.
on conflict (report_type,source_period,group_name,unit_name,position) do update set quota=excluded.quota,sort_group=excluded.sort_group,sort_unit=excluded.sort_unit,source_note=excluded.source_note;
on conflict (report_type,source_period,group_name,unit_name,position) do update set quota=excluded.quota,sort_group=excluded.sort_group,sort_unit=excluded.sort_unit,source_note=excluded.source_note;
